import asyncio
from nanobot_tools import forget

async def test():
    # 模拟工具调用结果
    messages = [
        {'role': 'assistant', 'tool_calls': [
            {'id': 'tc1', 'function': {'name': 'web_search', 'arguments': '{}'}}
        ]},
        {'role': 'tool', 'tool_call_id': 'tc1', 'content': 'Search result: ...'},
        {'role': 'assistant', 'tool_calls': [
            {'id': 'tc2', 'function': {'name': 'forget', 'arguments': '{\"keywords\": \"web_search\"}'}}
        ]},
        {'role': 'tool', 'tool_call_id': 'tc2', 'content': '__FORGET__:{\"tool_call_ids\": [\"tc1\"], \"names\": [\"web_search\"]}'},
    ]

    pending = [
        ({'id': 'tc1', 'function': {'name': 'web_search'}}, '{}', 'web_search'),
        ({'id': 'tc2', 'function': {'name': 'forget'}}, '{\"keywords\": \"web_search\"}', 'forget'),
    ]
    exec_results = [
        ('Search result: ...', None, None),
        ('__FORGET__:{\"tool_call_ids\": [\"tc1\"], \"names\": [\"web_search\"]}', None, None),
    ]

    # 模拟 tool_loop 的 forget 处理
    from collections import Counter
    import json

    _forget_ids = set()
    _forget_names = []
    for (tc, args_str, dedup_key), raw in zip(pending, exec_results):
        if isinstance(raw, BaseException):
            continue
        tool_result, _, _ = raw
        if isinstance(tool_result, str) and tool_result.startswith('__FORGET__:'):
            try:
                info = json.loads(tool_result[len('__FORGET__:'):])
                _forget_ids.update(info.get('tool_call_ids', []))
                _forget_names.extend(info.get('names', []))
            except Exception:
                pass

    if _forget_ids:
        _forget_self_ids = set()
        _id_to_name = {}
        for (tc, args_str, dedup_key), raw in zip(pending, exec_results):
            if isinstance(raw, BaseException):
                continue
            tool_result, _, _ = raw
            if isinstance(tool_result, str) and tool_result.startswith('__FORGET__:'):
                _forget_self_ids.add(tc.id)
                try:
                    info = json.loads(tool_result[len('__FORGET__:'):])
                    for tid, nm in zip(info.get('tool_call_ids', []), info.get('names', [])):
                        _id_to_name[tid] = nm
                except Exception:
                    pass

        for m in messages:
            if m.get('role') == 'tool' and m.get('tool_call_id') in _forget_ids:
                name = _id_to_name.get(m.get('tool_call_id', ''), '?')
                m['content'] = f'{name} → forgeted'

        for m in messages:
            if m.get('role') == 'assistant' and m.get('tool_calls'):
                for tc in m['tool_calls']:
                    if tc.get('id') in _forget_ids:
                        tc['forgot'] = True

        forget_msg = ', '.join(f'{n}×{c}' for n, c in Counter(_forget_names).items())
        for m in messages:
            if m.get('role') == 'tool' and m.get('tool_call_id') in _forget_self_ids:
                m['content'] = f'✓ forgot: {forget_msg}'

    print('=== After forget processing ===')
    for m in messages:
        print(f\"{m['role']}: {m.get('tool_calls') or m.get('content')}\")

asyncio.run(test())
